<body>
  <header>
    <nav class="nav wrap" aria-label="Main navigation">
      <a class="brand" href="#" aria-label="Dune Line home">
        <svg class="brand-mark" viewBox="0 0 40 40" fill="none" aria-hidden="true">
          <path d="M3 30 17 6h8L11 30H3Zm12 0L29 6h8L23 30h-8Z" fill="currentColor"/>
          <path d="M3 35h30" stroke="currentColor" stroke-width="3"/>
        </svg>
        <span class="brand-name"><span>DUNE</span><span>LINE</span></span>
      </a>
      <button class="menu-toggle" aria-expanded="false" aria-controls="nav-links">Menu <span aria-hidden="true">＋</span></button>
      <div class="nav-links" id="nav-links">
        <a href="#experience">The experience</a>
        <a href="#departures">Departures</a>
        <a href="#cabins">Cabins & fares</a>
        <a class="nav-book" href="#cabins">Find your seat <span class="arrow" aria-hidden="true">↗</span></a>
      </div>
    </nav>
  </header>

  <main>
    <section class="hero wrap" aria-labelledby="hero-title">
      <div class="hero-copy">
        <div class="route-label eyebrow">Solis desert <span aria-hidden="true">→</span> Lumen city</div>
        <h1 id="hero-title">Somewhere<br>between<br><em>sand & neon.</em></h1>
        <p class="hero-description">Leave the ordinary at the platform. Cross the desert under a sky full of stars, and wake up in a city that never runs out of light.</p>
        <div class="hero-actions">
          <a class="button" href="#departures">Find your night <span class="arrow" aria-hidden="true">↗</span></a>
          <div class="hero-note"><strong>From $89 one way</strong>A little further from everyday.</div>
        </div>
        <div class="hero-bottom"><span class="tiny-stars" aria-hidden="true">✦ ✦ ✦</span>Less rushing. More looking out the window.</div>
      </div>

      <figure class="poster">
        <svg viewBox="0 0 550 572" preserveAspectRatio="xMidYMid slice" role="img" aria-labelledby="landscape-title landscape-desc">
          <title id="landscape-title">The night train to Lumen</title>
          <desc id="landscape-desc">A silver train winds through rust-colored desert dunes toward a distant neon skyline beneath a giant setting sun and the first evening stars.</desc>
          <defs>
            <linearGradient id="sky" x1="0" y1="0" x2=".15" y2="1">
              <stop offset="0" stop-color="#292d43"/>
              <stop offset=".39" stop-color="#835965"/>
              <stop offset=".72" stop-color="#db8d73"/>
              <stop offset="1" stop-color="#edb17b"/>
            </linearGradient>
            <linearGradient id="sun" x2="0" y2="1">
              <stop stop-color="#f7dba2"/>
              <stop offset="1" stop-color="#ed9971"/>
            </linearGradient>
            <linearGradient id="frontDune" x1="0" y1="0" x2=".5" y2="1">
              <stop stop-color="#bc5c3f"/><stop offset="1" stop-color="#713e33"/>
            </linearGradient>
            <linearGradient id="trainSide" x1="0" y1="0" x2=".3" y2="1">
              <stop stop-color="#e7ddbd"/><stop offset=".6" stop-color="#bdbba7"/><stop offset="1" stop-color="#838d82"/>
            </linearGradient>
            <linearGradient id="glass" x2="1" y2="1">
              <stop stop-color="#313b3b"/><stop offset="1" stop-color="#536568"/>
            </linearGradient>
            <pattern id="windows" width="13" height="17" patternUnits="userSpaceOnUse">
              <rect x="3" y="3" width="2" height="5" fill="#e9ba91" opacity=".55"/>
              <rect x="8" y="3" width="2" height="5" fill="#edb3bb" opacity=".7"/>
            </pattern>
